export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export type Provider = "atlas" | "beacon";
export type RefusalReason = "unsupported_route" | "unsupported_parcel";

export interface CarrierRejection {
  provider: Provider;
  reason: RefusalReason;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: CarrierRejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: CarrierRejection[];
}

type StoredShipment = QueuedShipment | DispatchedShipment | DeferredShipment | UnavailableShipment;
export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

export interface DispatchAbortedBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: "unknown_failure" | "invalid_provider_response" | "repository_failure";
  rejections: CarrierRejection[];
}

export interface ServiceResponse {
  status: number;
  body: PublicShipment | DispatchAbortedBody | {
    code: "invalid_command" | "not_found";
  };
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type DispatchCommand = Extract<Command, { op: "dispatch" }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function copyRejections(rejections: CarrierRejection[]): CarrierRejection[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: copyRejections(shipment.rejections),
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: copyRejections(shipment.rejections),
  };
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

type CarrierFailure =
  | { kind: "refusal"; reason: RefusalReason }
  | { kind: "throttle"; retryAtMs: number }
  | { kind: "unknown" }
  | { kind: "malformed" };

function classifyCarrierFailure(provider: Provider, value: unknown, nowMs: number): CarrierFailure {
  if (!isObject(value)) {
    return { kind: "unknown" };
  }

  if (provider === "atlas") {
    if (value.code === "cannot_ship") {
      return isRefusalReason(value.reason)
        ? { kind: "refusal", reason: value.reason }
        : { kind: "malformed" };
    }
    if (value.code === "rate_limited") {
      return typeof value.retryAtMs === "number" &&
        Number.isSafeInteger(value.retryAtMs) &&
        value.retryAtMs > nowMs
        ? { kind: "throttle", retryAtMs: value.retryAtMs }
        : { kind: "malformed" };
    }
    return { kind: "unknown" };
  }

  if (value.type === "rejected") {
    return isObject(value.details) && isRefusalReason(value.details.reason)
      ? { kind: "refusal", reason: value.details.reason }
      : { kind: "malformed" };
  }
  if (value.type === "throttled") {
    return isObject(value.details) &&
      typeof value.details.retryAtMs === "number" &&
      Number.isSafeInteger(value.details.retryAtMs) &&
      value.details.retryAtMs > nowMs
      ? { kind: "throttle", retryAtMs: value.details.retryAtMs }
      : { kind: "malformed" };
  }
  return { kind: "unknown" };
}

function confirmationId(provider: Provider, value: unknown): string | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const id = provider === "atlas" ? value.bookingId : value.reference;
  return typeof id === "string" && id.length > 0 ? id : undefined;
}

function providerAlreadyRefused(provider: Provider, rejections: CarrierRejection[]): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

function abortBody(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: DispatchAbortedBody["classification"],
  rejections: CarrierRejection[],
): DispatchAbortedBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: copyRejections(rejections),
  };
}

function emitAbort(dependencies: ShippingDependencies, body: DispatchAbortedBody): void {
  dependencies.logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: copyRejections(body.rejections),
  });
}

function providerRequest(shipment: ShipmentFields, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function saveOrAbort(
    shipmentId: string,
    record: StoredShipment,
    rejections: CarrierRejection[],
  ): Promise<DispatchAbortedBody | undefined> {
    try {
      await dependencies.repository.save(shipmentId, record);
      return undefined;
    } catch {
      const body = abortBody(shipmentId, "repository", "repository_failure", rejections);
      emitAbort(dependencies, body);
      return body;
    }
  }

  async function dispatchFrom(
    shipment: StoredShipment,
    command: DispatchCommand,
    nextProvider: Provider,
    retainedRejections: CarrierRejection[],
  ): Promise<ServiceResponse> {
    const request = providerRequest(shipment, command.recipient);
    const rejections = copyRejections(retainedRejections);
    let provider: Provider | undefined = nextProvider;

    while (provider) {
      if (providerAlreadyRefused(provider, rejections)) {
        provider = provider === "atlas" ? "beacon" : undefined;
        continue;
      }

      let confirmation: unknown;
      try {
        confirmation = provider === "atlas"
          ? await dependencies.atlas.book(request)
          : await dependencies.beacon.reserve(request);
      } catch (error) {
        const failure = classifyCarrierFailure(provider, error, command.nowMs);
        if (failure.kind === "refusal") {
          rejections.push({ provider, reason: failure.reason });
          if (provider === "atlas" && !providerAlreadyRefused("beacon", rejections)) {
            provider = "beacon";
            continue;
          }

          const unavailable: UnavailableShipment = {
            schemaVersion: 1,
            id: shipment.id,
            routeCode: shipment.routeCode,
            parcelGrams: shipment.parcelGrams,
            state: "unavailable",
            rejections: copyRejections(rejections),
          };
          const abort = await saveOrAbort(shipment.id, unavailable, rejections);
          if (abort) {
            return { status: 500, body: abort };
          }
          dependencies.logger.info({
            shipmentId: shipment.id,
            action: "unavailable",
            rejections: copyRejections(rejections),
          });
          return { status: 422, body: publicShipment(unavailable) };
        }

        if (failure.kind === "throttle") {
          const deferred: DeferredShipment = {
            schemaVersion: 1,
            id: shipment.id,
            routeCode: shipment.routeCode,
            parcelGrams: shipment.parcelGrams,
            state: "deferred",
            nextProvider: provider,
            retryAtMs: failure.retryAtMs,
            rejections: copyRejections(rejections),
          };
          const abort = await saveOrAbort(shipment.id, deferred, rejections);
          if (abort) {
            return { status: 500, body: abort };
          }
          dependencies.logger.info({
            shipmentId: shipment.id,
            action: "deferred",
            provider,
            retryAtMs: failure.retryAtMs,
            rejections: copyRejections(rejections),
          });
          return { status: 202, body: publicShipment(deferred) };
        }

        const body = abortBody(
          shipment.id,
          provider,
          failure.kind === "malformed" ? "invalid_provider_response" : "unknown_failure",
          rejections,
        );
        emitAbort(dependencies, body);
        return { status: 500, body };
      }

      const bookingId = confirmationId(provider, confirmation);
      if (!bookingId) {
        const body = abortBody(shipment.id, provider, "invalid_provider_response", rejections);
        emitAbort(dependencies, body);
        return { status: 500, body };
      }

      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider,
        bookingId,
        dispatchedAtMs: command.nowMs,
      };
      const abort = await saveOrAbort(shipment.id, dispatched, rejections);
      if (abort) {
        return { status: 500, body: abort };
      }
      dependencies.logger.info({
        shipmentId: shipment.id,
        action: "dispatched",
        provider,
      });
      return { status: 200, body: publicShipment(dispatched) };
    }

    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections: copyRejections(rejections),
    };
    const abort = await saveOrAbort(shipment.id, unavailable, rejections);
    if (abort) {
      return { status: 500, body: abort };
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections: copyRejections(rejections),
    });
    return { status: 422, body: publicShipment(unavailable) };
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      const body = abortBody(command.shipmentId, "repository", "repository_failure", []);
      emitAbort(dependencies, body);
      return { status: 500, body };
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // Storage contains the host's queued records or this service's own saved JSON.
    const shipment = value as StoredShipment;
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred") {
      if (command.nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return dispatchFrom(shipment, command, shipment.nextProvider, shipment.rejections);
    }

    return dispatchFrom(shipment, command, "atlas", []);
  }

  return { handle };
}
